prototype_pollution.code_example:
// BAD: recursive merge that allows __proto__
function merge(target, src) {
  for (const k in src) {
    if (typeof src[k] === 'object') merge(target[k] = target[k] || {}, src[k]);
    else target[k] = src[k];
  }  // __proto__ flows through here!
}

// GOOD: block __proto__ / constructor.prototype
function safeMerge(target, src) {
  for (const k of Object.keys(src)) {
    if (k === '__proto__' || k === 'constructor' || k === 'prototype') continue;
    if (typeof src[k] === 'object' && src[k] !== null) {
      safeMerge(target[k] = target[k] || Object.create(null), src[k]);
    } else target[k] = src[k];
  }
}

